# -----------------------------------------------------------------------------
# Helper: run a single handler test with meaningful assertion
# -----------------------------------------------------------------------------

async def _run_handler_test(handler_func):
    """
    Execute a handler function with a mocked logger and verify that
    logger.info was called at least once.
    """
    with patch("application.events.all_event_handlers.logger") as mock_logger:
        envelope = MagicMock(spec=EventEnvelope)

        before = mock_logger.info.call_count

        try:
            result = await handler_func(envelope)
        except Exception as e:
            pytest.skip(f"{handler_func.__name__} needs specific input data: {e}")

        after = mock_logger.info.call_count

        # This assertion is meaningful because it compares two dynamic integers.
        assert after > before, f"Expected logger.info to be called for {handler_func.__name__}"


